#pragma once
#include "ksStateDisplayService.h"
#include "ksPanelHexTask.h"
#include <optional>
#include <stdexcept>
namespace ks {
// Reusable complete numeric/calibration presentation; direct number text and
// digit output keep their own typed children rather than borrowing menu phases.
class PanelSettingsLcdService final {
public:
 enum class Kind{Text,Character,Number,Digit,TwoZeros};
 enum class Component{Display,Number,Decimal,Text,Hex,Raw,Action,Poll,Byte};
 struct Input{uint16_t value=0,payload=0;uint32_t source=0;};struct Effect{bool read=false,write=false;};
 explicit PanelSettingsLcdService(Kind kind):PanelSettingsLcdService(kind,Input{}){}
 PanelSettingsLcdService(Kind kind,Input input):kind_(kind),input_(input),output_(input.payload){
  if(kind==Kind::Text||kind==Kind::Character){StateDisplayService::Input in;in.character=input.payload;in.source=input.source;display_.emplace(kind==Kind::Text?StateDisplayService::Kind::Text:StateDisplayService::Kind::Character,in);select(Component::Display);}
  else if(kind==Kind::Digit){hex_.emplace(PanelHexTask::Kind::Digit);select(Component::Hex);}
  else {number_.emplace(kind==Kind::TwoZeros?PanelFormatTask::Kind::TwoZeros:PanelFormatTask::Kind::ThreeSpaces);select(Component::Number);}
 }
 Kind kind()const{return kind_;}Component component()const{return component_;}uint32_t components()const{return components_;}bool complete()const{return complete_;}const Effect&effect()const{return effect_;}
 uint16_t output()const{return output_;}const Input&input()const{return input_;}const StateDisplayService::LcdResult&lcdResult()const{return result_;}
 const StateDisplayService*displayTask()const{return display_?&*display_:nullptr;}const PanelFormatTask*numberTask()const{return number_?&*number_:nullptr;}const PanelDecimalTask*decimalTask()const{return decimal_?&*decimal_:nullptr;}
 const PanelTextTask*textTask()const{return text_?&*text_:nullptr;}const PanelHexTask*hexTask()const{return component_==Component::Raw?raw_?&*raw_:nullptr:hex_?&*hex_:nullptr;}const PanelActionTask*actionTask()const{return action_?&*action_:nullptr;}const PanelPollTask*pollTask()const{return poll_?&*poll_:nullptr;}const PanelByteTask*byteTask()const{return byte_?&*byte_:nullptr;}
 unsigned nextClocks(int previous=-1)const{if(complete_)return 0;switch(component_){case Component::Display:return display_->nextClocks(previous);case Component::Number:return number_->nextClocks();case Component::Decimal:return decimal_->nextClocks();case Component::Text:return text_->nextClocks([]{return 3u;});case Component::Hex:return hex_->nextClocks();case Component::Raw:return raw_->nextClocks();case Component::Action:return action_->nextClocks();case Component::Poll:return poll_->nextClocks();case Component::Byte:return byte_->nextClocks([&](PanelByteTask::Port p){return portClock(p,previous);});}return 0;}
 template<class Reader,class Writer>unsigned advanceBefore(unsigned available,Reader&&rawRead,Writer&&rawWrite,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>available)return 0;effect_={};auto read=[&](uint32_t a,unsigned offset){a&=0xffffff;if(!resource(a))throw std::logic_error("Unsupported evolving panel settings read resource");return rawRead(a,offset);};auto write=[&](uint32_t a,uint8_t v,unsigned offset){a&=0xffffff;if(!resource(a))throw std::logic_error("Unsupported evolving panel settings write resource");rawWrite(a,v,offset);};switch(component_){
 case Component::Display:{effect_={display_->endsReadTransfer(),display_->endsWriteTransfer()};display_->advanceBefore(cost,read,write,previous);if(display_->complete()){output_=display_->output();result_=display_->lcdResult();complete_=true;}break;}
 case Component::Number:{using T=PanelFormatTask;using S=T::Stage;const auto stage=number_->stage();effect_.write=stage==S::RetainValue||stage==S::RetainPointer||stage==S::RetainFormat||stage==S::DispatchDecimal||stage==S::DispatchText;effect_.read=stage==S::RestoreFormat||stage==S::RestorePointer||stage==S::RestoreValue||stage==S::Finish;
  number_->advanceBefore(cost,[&](T::Read){return uint8_t(input_.value);},[&](int32_t at,uint8_t v){write(uint32_t(0xffec34+at)&0xffffff,v,cost);});if(number_->child()==T::Child::Decimal){decimal_.emplace();select(Component::Decimal);}else if(number_->child()==T::Child::Text){text_.emplace(PanelTextTask::Kind::Plain);select(Component::Text);}else if(stage==S::Finish)complete_=true;break;}
 case Component::Decimal:{using T=PanelDecimalTask;decimal_->advanceBefore(cost,[&](T::Read f){return f==T::Read::Padding?number_->padding():f==T::Read::Width?number_->width():number_->magnitude();},[&](int32_t at,uint8_t v){write(uint32_t(0xffec34+at)&0xffffff,v,cost);});if(decimal_->stage()==T::Stage::Complete){effect_.read=true;number_->resumeChild(decimal_->position());decimal_.reset();select(Component::Number);}break;}
 case Component::Text:{using T=PanelTextTask;using S=T::Stage;const auto stage=text_->stage();effect_.write=stage==S::HoldText||stage==S::DispatchText;effect_.read=stage==S::RestoreText||stage==S::Finish;text_->advanceBefore(cost,[&](T::Read f)->uint32_t{if(f==T::Read::Pointer)return 0xffec34;if(f==T::Read::Input)return uint8_t(output_);return read(text_->pointer()&0xffffff,cost-2);},[]{return 3u;});if(stage==S::ReadText)setByte(text_->byte());if(stage==S::RestoreText)output_=input_.payload;
  if(text_->child()==T::Child::Write){actionOwner_=Component::Text;startAction();}else if(text_->stage()==S::Complete){number_->resumeChild();select(Component::Number);}break;}
 case Component::Hex:case Component::Raw:{using T=PanelHexTask;using S=T::Stage;const auto component=component_;auto&t=component==Component::Hex?*hex_:*raw_;const auto stage=t.stage();effect_.write=stage==S::RetainInterrupt||stage==S::RetainConditions||stage==S::HoldInput||stage==S::HoldOutput||stage==S::DispatchDigit||stage==S::DispatchWrite;effect_.read=stage==S::RestoreInput||stage==S::RestoreConditions||stage==S::RestoreInterrupt||stage==S::RestoreOutput||stage==S::Finish;t.advanceBefore(cost,[&]{return component==Component::Hex?input_.value:hex_->argument();});if(stage==S::CopyOutput)setByte(t.output());if(stage==S::RestoreOutput)output_=input_.payload;
  if(t.child()==T::Child::Digit){raw_.emplace(T::Kind::Raw);select(Component::Raw);}else if(t.child()==T::Child::Write){actionOwner_=Component::Raw;startAction();}else if(t.stage()==S::Complete){if(component==Component::Raw){hex_->resumeChild();select(Component::Hex);}else complete_=true;}break;}
 case Component::Action:{using T=PanelActionTask;using S=T::Stage;const auto stage=action_->stage();effect_.write=stage==S::Hold||stage==S::Poll||stage==S::PollAgain||stage==S::CommandByte||stage==S::DataByte;effect_.read=stage==S::Restore||stage==S::Finish;action_->advanceBefore(cost,[&](T::Read f){return f==T::Read::Input?uint8_t(output_):uint8_t(output_>>8);});if(stage==S::Restore||stage==S::SetAddress)setByte(action_->input());if(stage==S::CompareReply)result_={PanelTextTask::Action::Write,action_->input(),action_->reply(),true};
  if(action_->child()==T::Child::Poll){poll_.emplace();select(Component::Poll);}else if(action_->child()==T::Child::CommandByte||action_->child()==T::Child::DataByte){byteFromPoll_=false;byte_.emplace(action_->child()==T::Child::CommandByte?PanelByteTask::Kind::CommandWrite:PanelByteTask::Kind::DataWrite);select(Component::Byte);}else if(action_->stage()==S::Complete){action_.reset();if(actionOwner_==Component::Text){text_->resumeChild();select(Component::Text);}else {raw_->resumeChild();select(Component::Raw);}}break;}
 case Component::Poll:{using T=PanelPollTask;effect_.write=poll_->stage()==T::Stage::DispatchStatus||poll_->stage()==T::Stage::DispatchFinal;effect_.read=poll_->stage()==T::Stage::Finish;poll_->advanceBefore(cost);if(poll_->awaiting()){byteFromPoll_=true;byte_.emplace(PanelByteTask::Kind::CommandRead);select(Component::Byte);}else if(poll_->stage()==T::Stage::Complete){action_->resumeChild(poll_->reply());poll_.reset();select(Component::Action);}break;}
 case Component::Byte:{using T=PanelByteTask;effect_.write=byte_->stage()==T::Stage::Hold;effect_.read=byte_->stage()==T::Stage::RestoreHeld||byte_->stage()==T::Stage::Finish;byte_->advanceBefore(cost,[&](T::Read f){return f==T::Read::Input?uint8_t(output_):uint8_t(read(0xffff51,cost));},[&](T::Port p,uint8_t value){write(portAddress(p),value,cost);},[&](T::Port p){return portClock(p,previous);});if(byte_->reading()&&byte_->stage()==T::Stage::RestoreControl)setByte(byte_->data());if(byte_->stage()==T::Stage::Complete){const auto reply=uint8_t(output_);byte_.reset();if(byteFromPoll_){poll_->resumeChild(reply);select(Component::Poll);}else {action_->resumeChild(reply);select(Component::Action);}}break;}
 }return cost;}
private:
 static bool resource(uint32_t a){return StateDisplayService::dataSpan(a,1)||(a>=0x800000&&a<0x900000)||a==0xffff51||a==0xffff61||a==0xffff62||a==0xfffeb1||a==0xffffa4||a==0xffffa5||a==0xffffa6||a==0xfffff6||a==0xfffff7||a==0xffff98||a==0xffff6e;}
 static uint32_t portAddress(PanelByteTask::Port p){return p==PanelByteTask::Port::Gate?0xfffeb1:p==PanelByteTask::Port::Control?0xffff62:0xffff61;}static unsigned portClock(PanelByteTask::Port p,int previous){const auto a=portAddress(p);return(a&1)&&previous==int(a-1)?0:1;}
 void setByte(uint8_t v){output_=uint16_t((output_&0xff00)|v);}void select(Component c){component_=c;components_|=1u<<unsigned(c);}void startAction(){action_.emplace(PanelActionTask::Kind::WriteData);select(Component::Action);}
 Kind kind_;Input input_;Component component_=Component::Display,actionOwner_=Component::Text;Effect effect_{};uint32_t components_=0;uint16_t output_=0;bool complete_=false,byteFromPoll_=false;StateDisplayService::LcdResult result_{};
 std::optional<StateDisplayService>display_;std::optional<PanelFormatTask>number_;std::optional<PanelDecimalTask>decimal_;std::optional<PanelTextTask>text_;std::optional<PanelHexTask>hex_,raw_;std::optional<PanelActionTask>action_;std::optional<PanelPollTask>poll_;std::optional<PanelByteTask>byte_;
};
}
